// pnpm --filter @crewarcade/server db:migrate
// Applies the SQL migrations in apps/server/drizzle/ (generated by `db:generate`) in order.
import path from 'node:path';
import { loadDbScriptConfig } from '../config';
import { runMigrations } from './migrations';

const config = loadDbScriptConfig();
const folder = await runMigrations(config.DATABASE_URL);
console.log(`Migrations applied from ${path.relative(process.cwd(), folder) || folder}`);
